package com.villofarm.security;
import com.villofarm.repository.UserRepository;import jakarta.servlet.FilterChain;import jakarta.servlet.ServletException;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var auth=req.getHeader("Authorization");if(auth!=null&&auth.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{var email=jwt.subject(auth.substring(7));users.findByEmailIgnoreCase(email).ifPresent(user->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,null,List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole().name())))));}catch(Exception ignored){}}chain.doFilter(req,res);}}
